def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the DP table
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N * N + 1)]
    dp[0][0][0] = grid[0][0]

    # Directions for moving in the grid (right and down)
    directions = [(0, 1), (1, 0)]

    # Fill the DP table
    for t in range(1, 2 * N - 1):
        for i in range(max(0, t - (N - 1)), min(N, t + 1)):
            for j in range(max(0, t - (N - 1)), min(N, t + 1)):
                if i + j != t:
                    continue
                for di, dj in directions:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < N and 0 <= nj < N:
                        for di2, dj2 in directions:
                            ni2, nj2 = i + di2, j + dj2
                            if 0 <= ni2 < N and 0 <= nj2 < N:
                                if (ni, nj) == (ni2, nj2):
                                    dp[t][ni][nj] = max(dp[t][ni][nj], dp[t-1][i][j] + grid[ni][nj])
                                else:
